//! Adobe's predefined CJK encoding CMaps (code → CID): Shift-JIS, EUC, GBK,
//! Big5, UHC and the rest of ISO 32000-2 Table 118.
//!
//! A composite font may name one of these as its `/Encoding` instead of
//! `Identity-H`; its show strings are then legacy multi-byte codes (one or two
//! bytes each, by the CMap's codespace). This module splits them into codes
//! and maps each code to a CID; the collection tables (`cid2uni`) turn CIDs
//! into text, and the font's `/W` gives their widths.
//!
//! Data: `src/data/cjk-cmaps.bin.z`, generated by `scripts/gen-cjk-cmaps.py`
//! from Adobe's cmap-resources (BSD-3-Clause), inflated on first use.

use std::collections::HashMap;
use std::io::Read;
use std::sync::{Arc, Mutex, OnceLock};

use super::cid2uni::Collection;

static BLOB: &[u8] = include_bytes!("../data/cjk-cmaps.bin.z");

/// One predefined encoding CMap.
pub struct EncodingCMap {
    pub collection: Collection,
    /// `(length, low bytes, high bytes)`.
    spaces: Vec<(usize, [u8; 4], [u8; 4])>,
    /// `(length, low code, high code, first CID)`, sorted by `(length, low)`.
    ranges: Vec<(u8, u32, u32, u32)>,
}

impl EncodingCMap {
    /// Length of the code at the start of `bytes`: the codespace range it
    /// falls in, else one byte (a malformed byte is skipped, not merged into
    /// the next code).
    pub fn code_len(&self, bytes: &[u8]) -> usize {
        self.spaces
            .iter()
            .filter(|(len, ..)| *len <= bytes.len())
            .find(|(len, lo, hi)| (0..*len).all(|k| lo[k] <= bytes[k] && bytes[k] <= hi[k]))
            .map_or(1, |(len, ..)| *len)
    }

    /// CID of one code (as split by `code_len`).
    pub fn cid(&self, code: &[u8]) -> Option<u32> {
        if code.is_empty() || code.len() > 4 {
            return None;
        }
        let len = code.len() as u8;
        let value = code.iter().fold(0u32, |a, &b| (a << 8) | u32::from(b));
        let at = self.ranges.partition_point(|r| (r.0, r.1) <= (len, value));
        let r = self.ranges[..at].last()?;
        (r.0 == len && value <= r.2).then(|| r.3 + (value - r.1))
    }
}

/// The predefined CMap called `name` (a vertical `-V` CMap is read through its
/// horizontal twin: the two differ only in vertical punctuation forms).
pub fn predefined(name: &str) -> Option<Arc<EncodingCMap>> {
    let name = if name == "V" {
        "H".to_owned()
    } else if let Some(stem) = name.strip_suffix("-V") {
        format!("{stem}-H")
    } else {
        name.to_owned()
    };
    static CACHE: OnceLock<Mutex<HashMap<String, Option<Arc<EncodingCMap>>>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(hit) = cache.lock().ok().and_then(|m| m.get(&name).cloned()) {
        return hit;
    }
    let parsed = parse(&name).map(Arc::new);
    if let Ok(mut m) = cache.lock() {
        m.insert(name, parsed.clone());
    }
    parsed
}

fn data() -> &'static [u8] {
    static RAW: OnceLock<Vec<u8>> = OnceLock::new();
    RAW.get_or_init(|| {
        let mut out = Vec::new();
        // The blob is ours and small (~270 KB inflated); cap it anyway.
        let _ = flate2::read::ZlibDecoder::new(BLOB)
            .take(4 << 20)
            .read_to_end(&mut out);
        out
    })
}

fn parse(name: &str) -> Option<EncodingCMap> {
    let d = data();
    let mut r = Reader { d, i: 0 };
    let count = r.u16()?;
    let mut found = None;
    for _ in 0..count {
        let n = usize::from(r.u8()?);
        let entry_name = r.bytes(n)?;
        let col = r.u8()?;
        let (off, len) = (r.u32()? as usize, r.u32()? as usize);
        if entry_name == name.as_bytes() {
            found = Some((col, off, len));
        }
    }
    let (col, off, len) = found?;
    let body_start = r.i;
    let body = d.get(body_start + off..body_start + off + len)?;
    let mut b = Reader { d: body, i: 0 };
    let collection = match col {
        0 => Collection::Japan1,
        1 => Collection::Gb1,
        2 => Collection::Cns1,
        _ => Collection::Korea1,
    };
    let n_spaces = usize::from(b.u8()?);
    let mut spaces = Vec::with_capacity(n_spaces);
    for _ in 0..n_spaces {
        let len = usize::from(b.u8()?);
        let lo: [u8; 4] = b.bytes(4)?.try_into().ok()?;
        let hi: [u8; 4] = b.bytes(4)?.try_into().ok()?;
        spaces.push((len, lo, hi));
    }
    let n_ranges = b.u32()? as usize;
    let mut ranges = Vec::with_capacity(n_ranges.min(1 << 17));
    for _ in 0..n_ranges {
        ranges.push((b.u8()?, b.u32()?, b.u32()?, b.u32()?));
    }
    Some(EncodingCMap {
        collection,
        spaces,
        ranges,
    })
}

struct Reader<'a> {
    d: &'a [u8],
    i: usize,
}

impl<'a> Reader<'a> {
    fn bytes(&mut self, n: usize) -> Option<&'a [u8]> {
        let s = self.d.get(self.i..self.i + n)?;
        self.i += n;
        Some(s)
    }
    fn u8(&mut self) -> Option<u8> {
        self.bytes(1).map(|b| b[0])
    }
    fn u16(&mut self) -> Option<u16> {
        self.bytes(2).map(|b| u16::from_le_bytes([b[0], b[1]]))
    }
    fn u32(&mut self) -> Option<u32> {
        self.bytes(4)
            .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shift_jis_codes_split_and_map() {
        let m = predefined("90ms-RKSJ-H").unwrap();
        assert_eq!(m.collection, Collection::Japan1);
        // "Aあ" in Shift-JIS: 0x41 (one byte), 0x82A0 (two bytes).
        let bytes = [0x41, 0x82, 0xA0];
        assert_eq!(m.code_len(&bytes), 1);
        assert_eq!(m.code_len(&bytes[1..]), 2);
        let a = m.cid(&[0x41]).unwrap();
        let hira = m.cid(&[0x82, 0xA0]).unwrap();
        assert_eq!(Collection::Japan1.to_char(a), Some('A'));
        assert_eq!(Collection::Japan1.to_char(hira), Some('あ'));
        // The vertical name resolves to the same mapping.
        assert!(predefined("90ms-RKSJ-V").is_some());
    }

    #[test]
    fn other_collections() {
        let gbk = predefined("GBK-EUC-H").unwrap();
        // 中 = GBK D6D0
        let cid = gbk.cid(&[0xD6, 0xD0]).unwrap();
        assert_eq!(Collection::Gb1.to_char(cid), Some('中'));
        let b5 = predefined("ETen-B5-H").unwrap();
        // 中 = Big5 A4A4
        assert_eq!(
            Collection::Cns1.to_char(b5.cid(&[0xA4, 0xA4]).unwrap()),
            Some('中')
        );
        let uhc = predefined("KSCms-UHC-H").unwrap();
        // 한 = UHC C7D1
        assert_eq!(
            Collection::Korea1.to_char(uhc.cid(&[0xC7, 0xD1]).unwrap()),
            Some('한')
        );
        assert!(predefined("NoSuch-H").is_none());
    }
}
